CREATE TABLE matches (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            date_text TEXT NOT NULL,
            date_iso TEXT,
            opponent_team_id INTEGER,
            competition_id INTEGER,
            location TEXT NOT NULL,
            vasco_goals INTEGER NOT NULL,
            opponent_goals INTEGER NOT NULL,
            observation TEXT NOT NULL DEFAULT '',
            coach_id INTEGER,
            table_position INTEGER,
            lineup_json TEXT NOT NULL DEFAULT '{}', stadium TEXT NOT NULL DEFAULT '', match_time TEXT NOT NULL DEFAULT '', captain_name TEXT NOT NULL DEFAULT '', paid_attendance INTEGER, total_attendance INTEGER, match_revenue REAL, arbitration_json TEXT NOT NULL DEFAULT '{}',
            FOREIGN KEY (opponent_team_id) REFERENCES teams (id),
            FOREIGN KEY (competition_id) REFERENCES competitions (id),
            FOREIGN KEY (coach_id) REFERENCES coaches (id)
        );
