INSERT INTO matches VALUES(208428,'04/04/2026','2026-04-04',1190,2174,'casa',1,2,'Achei que a torcida organizada do Vasco pesou a mão em sacanear o Botafogo... um jogo aleatorio do campeonato Brasileiro colocaram mosaico chamando o Botafogo de bairro e listando todas as goleadas, dando armas para eles...em fim ne....',2439,10,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Cauan Barros", "Tche Tche", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Carlos Cuesta", "Lucas Freitas", "Lucas Piton", "Hugo Moura", "JP", "Nuno Moreira", "Adson", "Claudio Spinelli", "Marino", "Matheus França"], "reservas_que_entraram": ["Nuno Moreira", "Claudio Spinelli", "Marino"], "substituicoes": [{"jogador_entrou": "Marino", "jogador_saiu": "Johan Rojas", "minuto": 22, "periodo": "2T", "minuto_absoluto": 67}, {"jogador_entrou": "Nuno Moreira", "jogador_saiu": "Tche Tche", "minuto": 24, "periodo": "2T", "minuto_absoluto": 69}, {"jogador_entrou": "Claudio Spinelli", "jogador_saiu": "David", "minuto": 32, "periodo": "2T", "minuto_absoluto": 77}], "nao_relacionados": ["Allan Vitor", "Pablo", "João Vitor", "Walace Falcão", "Avellar"], "lesionados": ["Jair", "Mateus Carvalho", "Brenner"], "suspensos": [], "servindo_selecao": []}','São Januário','21:00','Thiago Mendes',19369,20072,1385294.0,'{"arbitro": "Wagner do Nascimento Magalhaes", "auxiliares": ["Bruno Boschilia", "Luiz Claudio Regazone"], "var": "Rodrigo D''Alonso Ferreira"}');
INSERT INTO matches VALUES(208429,'07/04/2026','2026-04-07',259114,682,'fora',0,0,unistr('Vasco jogou a estreia da Sul-americana com time totalmente reserva.\u000aEsse jogo o Renato Gaucho não viajou e o Vasco foi comandado pelo auxiliar do Renato, o Marcelo Salles.'),2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Daniel Fuzato"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Carlos Cuesta", "Lucas Freitas", "Walace Falcão"], "Lateral-Esquerdo": ["Avellar"], "Volante": ["Hugo Moura"], "Meio-Campista": ["JP", "Matheus França", "Nuno Moreira"], "Atacante": ["Claudio Spinelli"]}, "reservas": ["Pablo", "Phillipe Gabriel", "Breno Vereza", "Bruno André", "João Vitor", "Alison", "Gustavo Guimarães", "Lukas Zucarello", "Ramon Rique", "Samuel Jesus", "Adson", "Andrey Fernandes", "Juninho", "Marino"], "reservas_que_entraram": ["Lukas Zucarello", "Adson", "Marino"], "substituicoes": [{"jogador_entrou": "Adson", "jogador_saiu": "Matheus França", "minuto": 25, "periodo": "2T", "minuto_absoluto": 70}, {"jogador_entrou": "Marino", "jogador_saiu": "Avellar", "minuto": 25, "periodo": "2T", "minuto_absoluto": 70}, {"jogador_entrou": "Lukas Zucarello", "jogador_saiu": "Nuno Moreira", "minuto": 36, "periodo": "2T", "minuto_absoluto": 81}], "nao_relacionados": ["Allan Vitor", "Léo Jardim", "Paulo Henrique", "Robert Renan", "Saldivia", "Cuiabano", "Lucas Piton", "Cauan Barros", "Tche Tche", "Thiago Mendes", "Johan Rojas", "Andrés Gómez", "David"], "lesionados": ["Jair", "Mateus Carvalho", "Brenner"], "suspensos": [], "servindo_selecao": []}','Florencio Sola','19:00','Hugo Moura',NULL,NULL,NULL,'{"arbitro": "Carlos Bentancur (COL)", "auxiliares": ["Alexander Guzman (COL)", "Jhon Gallego (COL)"], "var": "Leonard Mosquera (COL"}');
INSERT INTO matches VALUES(208430,'11/04/2026','2026-04-11',1446,2174,'fora',1,1,'Jogo começou as 17h devido as chuvas.... e Vasco cede o resultado novamente....',2439,11,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Robert Renan", "Saldivia"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Cauan Barros", "Tche Tche", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Andrés Gómez", "David"]}, "reservas": ["Daniel Fuzato", "Carlos Cuesta", "Lucas Freitas", "Lucas Piton", "Hugo Moura", "JP", "Matheus França", "Nuno Moreira", "Adson", "Brenner", "Claudio Spinelli", "Marino"], "reservas_que_entraram": ["JP", "Brenner", "Claudio Spinelli", "Marino"], "substituicoes": [{"jogador_entrou": "Brenner", "jogador_saiu": "David", "minuto": 18, "periodo": "2T", "minuto_absoluto": 63}, {"jogador_entrou": "JP", "jogador_saiu": "Cauan Barros", "minuto": 18, "periodo": "2T", "minuto_absoluto": 63}, {"jogador_entrou": "Marino", "jogador_saiu": "Johan Rojas", "minuto": 32, "periodo": "2T", "minuto_absoluto": 77}, {"jogador_entrou": "Claudio Spinelli", "jogador_saiu": "Tche Tche", "minuto": 43, "periodo": "2T", "minuto_absoluto": 88}], "nao_relacionados": ["Allan Vitor", "Pablo", "Phillipe Gabriel", "Breno Vereza", "Bruno André", "João Vitor", "Walace Falcão", "Alison", "Avellar", "Gustavo Guimarães", "Lukas Zucarello", "Ramon Rique", "Samuel Jesus", "Andrey Fernandes", "Juninho"], "lesionados": ["Jair", "Mateus Carvalho"], "suspensos": ["Puma Rodríguez"], "servindo_selecao": []}','Mangueirão','16:30','',NULL,NULL,NULL,'{"arbitro": "Rodrigo José Pereira De Lima", "auxiliares": ["Luanderson Lima Dos Santos", "Francisco Chaves Bezerra Junior"], "var": "Pablo Ramon Goncalves Pinheiro"}');
INSERT INTO matches VALUES(208431,'14/04/2026','2026-04-14',259325,682,'casa',1,2,'Jogo horrivel do Vasco... time sem vontade, sem querer jogar, mas o craque da partida foi o melhor jogador do Audax Italiano! O senhor Hernán Heras, arbitro da partida que marcou penalti e expulsou o fraco jogador do Vasco, nosso Leo Pele piorado Cuesta.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Carlos Cuesta", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura", "JP"], "Meio-Campista": ["Nuno Moreira", "Marino"], "Atacante": ["Brenner", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Walace Falcão", "Robert Renan", "Cuiabano", "Thiago Mendes", "Tche Tche", "Matheus França", "Johan Rojas", "Andrés Gómez", "Adson", "David"], "reservas_que_entraram": [], "substituicoes": [], "nao_relacionados": ["Allan Vitor", "Pablo", "Phillipe Gabriel", "Breno Vereza", "Bruno André", "João Vitor", "Saldivia", "Alison", "Avellar", "Cauan Barros", "Gustavo Guimarães", "Lukas Zucarello", "Ramon Rique", "Samuel Jesus", "Andrey Fernandes", "Juninho"], "lesionados": ["Jair", "Mateus Carvalho"], "suspensos": [], "servindo_selecao": []}','São Januário','21:00','',12495,13084,719790.0,'{"arbitro": "Hernán Heras", "auxiliares": ["Agustín Berisso", "Andres Nievas"], "var": "Diego Dunajec"}');
