INSERT INTO matches VALUES(208433,'21/04/2026','2026-04-21',5182,681,'fora',2,0,'Estreia do Vasco na 5ª fase da Copa do Brasil 2026 (jogo de ida). Gol de Nuno Moreira anulado pelo VAR por falta em jogada anterior. ⚠️ VERIFICAR: minutos das substituições são estimados — confirmar em Sofascore ou CBF.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Saldivia", "Robert Renan"], "Lateral-Esquerdo": ["Cuiabano"], "Volante": ["Cauan Barros", "Thiago Mendes"], "Meio-Campista": ["Tche Tche"], "Atacante": ["Johan Rojas", "Andrés Gómez", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Lucas Piton", "Carlos Cuesta", "Lucas Freitas", "Hugo Moura", "Matheus França", "Marino", "Nuno Moreira", "Adson", "Brenner", "David"], "reservas_que_entraram": ["Hugo Moura", "Matheus França", "Nuno Moreira", "Adson", "Brenner"], "substituicoes": [{"jogador_entrou": "Adson", "jogador_saiu": "Tche Tche", "minuto": 28, "periodo": "2T", "minuto_absoluto": 73}, {"jogador_entrou": "Matheus França", "jogador_saiu": "Thiago Mendes", "minuto": 28, "periodo": "2T", "minuto_absoluto": 73}, {"jogador_entrou": "Hugo Moura", "jogador_saiu": "Andrés Gómez", "minuto": 35, "periodo": "2T", "minuto_absoluto": 80}, {"jogador_entrou": "Nuno Moreira", "jogador_saiu": "Johan Rojas", "minuto": 35, "periodo": "2T", "minuto_absoluto": 80}, {"jogador_entrou": "Brenner", "jogador_saiu": "Claudio Spinelli", "minuto": 40, "periodo": "2T", "minuto_absoluto": 85}], "nao_relacionados": ["Allan Vitor", "Pablo", "Phillipe Gabriel", "Breno Vereza", "Bruno André", "João Vitor", "Walace Falcão", "Alison", "Avellar", "Gustavo Guimarães", "Lukas Zucarello", "Ramon Rique", "Samuel Jesus", "Andrey Fernandes", "Juninho"], "lesionados": ["Jair", "Mateus Carvalho"], "suspensos": ["JP"], "servindo_selecao": []}','Mangueirão','21:30','Thiago Mendes',NULL,NULL,NULL,'{"arbitro": "Ramon Abatti Abel", "auxiliares": ["Alex dos Santos", "Henrique Neu Ri