INSERT INTO matches VALUES(208435,'30/04/2026','2026-04-30',259564,682,'casa',3,0,'Renato Gaúcho estava suspenso pela Conmebol; Alexandre Mendes comandou a equipe à beira do campo.',249336,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Saldivia", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura"], "Meio-Campista": ["Ramon Rique", "Johan Rojas", "Nuno Moreira"], "Atacante": ["Adson", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Paulo Henrique", "Avellar", "Walace Falcão", "Robert Renan", "Cauan Barros", "Matheus França", "Lukas Zucarello", "Marino", "Brenner", "David"], "reservas_que_entraram": ["Paulo Henrique", "Avellar", "Cauan Barros", "Marino", "Brenner"], "substituicoes": [{"jogador_saiu": "Puma Rodríguez", "jogador_entrou": "Paulo Henrique", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Lucas Piton", "jogador_entrou": "Avellar", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Ramon Rique", "jogador_entrou": "Cauan Barros", "minuto": 24, "periodo": "2T"}, {"jogador_saiu": "Johan Rojas", "jogador_entrou": "Marino", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Adson", "jogador_entrou": "Brenner", "minuto": 31, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Andrés Gómez", "Breno Vereza", "Bruno André", "Gustavo Guimarães", "João Vitor", "Juninho", "Pablo", "Phillipe Gabriel", "Samuel Jesus"], "lesionados": ["Jair", "Mateus Carvalho", "Thiago Mendes", "Cuiabano"], "suspensos": ["Carlos Cuesta", "JP"], "servindo_selecao": []}','São Januário','19:00','Puma Rodríguez',11954,12543,707458.0,'{"arbitro": "Jesús Valenzuela", "auxiliares": ["Tulio Moreno", "Alberto Ponte"], "var": "Carlos Orbe"}');
INSERT INTO matches VALUES(208436,'03/05/2026','2026-05-03',4371,2174,'fora',2,2,'Vasco buscou empate no fim no Maracanã: Robert Renan diminuiu de cabeça após escanteio de Nuno Moreira e Hugo Moura empatou no último lance após bola de Carlos Cuesta na área. Gol de David no fim do 1º tempo foi anulado por impedimento.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Carlos Cuesta", "Robert Renan"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Cauan Barros", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Puma Rodríguez", "Brenner", "David"]}, "reservas": ["Andrés Gómez", "Claudio Spinelli", "Adson", "Nuno Moreira", "Hugo Moura", "Daniel Fuzato", "Saldivia", "Lucas Freitas", "Avellar", "Tche Tche", "JP", "Marino"], "reservas_que_entraram": ["Andrés Gómez", "Claudio Spinelli", "Adson", "Nuno Moreira", "Hugo Moura"], "substituicoes": [{"jogador_saiu": "David", "jogador_entrou": "Andrés Gómez", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Brenner", "jogador_entrou": "Claudio Spinelli", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Paulo Henrique", "jogador_entrou": "Adson", "minuto": 20, "periodo": "2T"}, {"jogador_saiu": "Johan Rojas", "jogador_entrou": "Nuno Moreira", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Cauan Barros", "jogador_entrou": "Hugo Moura", "minuto": 36, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Breno Vereza", "Bruno André", "Gustavo Guimarães", "João Vitor", "Juninho", "Lukas Zucarello", "Matheus França", "Pablo", "Phillipe Gabriel", "Ramon Rique", "Samuel Jesus", "Walace Falcão"], "lesionados": ["Cuiabano", "Jair", "Mateus Carvalho"], "suspensos": [], "servindo_selecao": []}','Maracanã','16:00','',NULL,NULL,NULL,'{"arbitro": "Wilton Pereira Sampaio", "auxiliares": ["Bruno Boschilia", "Leone Carvalho Rocha"], "var": "Daniel Nobre Bins"}');
INSERT INTO matches VALUES(208437,'06/05/2026','2026-05-06',276347,682,'fora',2,1,'Vasco venceu de virada fora de casa pela 4ª rodada do Grupo G da Copa Sul-Americana (7 pts, liderança). Gol do Audax foi gol contra de Saldivia (jogador do Vasco) aos 5''/1T — registrado em gols_adversario com nome Saldivia. Spinelli marcou de pênalti. Ortiz (Audax) foi expulso aos 17''/2T. Renato Gaúcho suspenso pela Conmebol (3 jogos) — Alexandre Mendes assumiu como técnico interino. Vasco usou time alternativo com cerca de 10 atletas do sub-20. Árbitro Jhon Ospina (COL), auxiliar David Fuentes (COL) e VAR Ricardo Garcia (COL) são novos no banco — cadastrar antes de importar. Auxiliar normalizado para Jhon Gallego (COL) conforme banco. Estádio Bicentenário de La Florida não cadastrado no banco — cadastrar antes de importar. Ambiguidade: fonte cita Riquelme Avellar como um único jogador; banco tem Avellar e Riquelme separados — usou-se Avellar como o substituto de Nuno Moreira. Capitão não identificado em fonte confiável — campo em branco. Público pagante, público presente e renda não encontrados em nenhuma fonte — preencher antes de importar ou confirmar null.',249336,NULL,'{"titulares_por_posicao": {"Goleiro": ["Daniel Fuzato"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Saldivia", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Cauan Barros", "JP", "Tche Tche"], "Meio-Campista": ["Marino", "Nuno Moreira"], "Atacante": ["Claudio Spinelli"]}, "reservas": ["Pablo", "Breno Vereza", "Avellar", "Walace Falcão", "Bruno André", "Alison", "Samuel Jesus", "Gustavo Guimarães", "Ramon Rique", "Matheus França", "Lukas Zucarello", "Andrey Fernandes"], "substituicoes": [{"jogador_saiu": "JP", "jogador_entrou": "Matheus França", "minuto": 0, "periodo": "INT"}, {"jogador_saiu": "Tche Tche", "jogador_entrou": "Ramon Rique", "minuto": 0, "periodo": "INT"}, {"jogador_saiu": "Marino", "jogador_entrou": "Lukas Zucarello", "minuto": 43, "periodo": "2T"}, {"jogador_saiu": "Lucas Piton", "jogador_entrou": "Walace Falcão", "minuto": 44, "periodo": "2T"}, {"jogador_saiu": "Nuno Moreira", "jogador_entrou": "Avellar", "minuto": 44, "periodo": "2T"}], "nao_relacionados": ["Adson", "Allan Vitor", "Andrés Gómez", "Brenner", "Carlos Cuesta", "David", "Hugo Moura", "Johan Rojas", "João Vitor", "Juninho", "Léo Jardim", "Phillipe Gabriel", "Puma Rodríguez", "Robert Renan", "Thiago Mendes"], "lesionados": ["Jair", "Mateus Carvalho", "Cuiabano"], "suspensos": [], "servindo_selecao": []}','Estádio Bicentenário de La Florida','19:00','',NULL,NULL,NULL,'{"arbitro": "Jhon Ospina (COL)", "auxiliares": ["David Fuentes (COL)", "Jhon Gallego (COL)"], "var": "Ricardo Garcia (COL)"}');
INSERT INTO matches VALUES(208438,'10/05/2026','2026-05-10',1309,2174,'casa',1,0,'Vasco venceu o Athletico-PR por 1 a 0 em São Januário pela 15ª rodada do Campeonato Brasileiro de 2026 e terminou a rodada na 8ª colocação, com 20 pontos. Gol de Thiago Mendes aos 36''/1T, com assistência de Puma Rodríguez segundo relato da NetVasco. A súmula registrou Thiago Mendes aos 36:00/1T e cartões amarelos para Thiago Mendes aos 7''/1T, Johan Rojas aos 17''/2T, Robert Renan aos 24''/2T e Andrés Gómez aos 44''/2T; não houve expulsões. Paulo Henrique e Cauan Barros estavam suspensos pelo terceiro cartão amarelo; Jair e Mateus Carvalho eram desfalques por lesão no joelho. Cuiabano não foi relacionado porque foi preservado enquanto se recuperava de edema na coxa esquerda. A súmula lista o reserva 82 como Riquelme Avellar; no banco local foi normalizado como Avellar. Raphael Claus, Danilo Ricardo Simon Manis e Wagner Reway não foram encontrados nas listas locais de árbitros/auxiliares/VAR; cadastrar antes de importar se o importador não criar automaticamente. Nada houve de anormal segundo a súmula; foi respeitado 1 minuto de silêncio em homenagens póstumas.',2439,8,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Puma Rodríguez"], "Zagueiro": ["Carlos Cuesta", "Robert Renan"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Hugo Moura", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas"], "Atacante": ["Adson", "Andrés Gómez", "Claudio Spinelli"]}, "reservas": ["Daniel Fuzato", "Tche Tche", "Saldivia", "David", "Matheus França", "Nuno Moreira", "Marino", "Brenner", "Lucas Freitas", "Avellar", "Ramon Rique", "JP"], "substituicoes": [{"jogador_saiu": "Johan Rojas", "jogador_entrou": "Tche Tche", "minuto": 22, "periodo": "2T"}, {"jogador_saiu": "Claudio Spinelli", "jogador_entrou": "Brenner", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Adson", "jogador_entrou": "Nuno Moreira", "minuto": 31, "periodo": "2T"}, {"jogador_saiu": "Lucas Piton", "jogador_entrou": "Lucas Freitas", "minuto": 45, "periodo": "2T"}, {"jogador_saiu": "Andrés Gómez", "jogador_entrou": "Ramon Rique", "minuto": 45, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Breno Vereza", "Bruno André", "Gustavo Guimarães", "João Vitor", "Juninho", "Lukas Zucarello", "Pablo", "Phillipe Gabriel", "Samuel Jesus", "Walace Falcão"], "lesionados": ["Jair", "Mateus Carvalho", "Cuiabano"], "suspensos": ["Paulo Henrique", "Cauan Barros"], "servindo_selecao": []}','São Januário','20:30','Thiago Mendes',13315,13917,898312.0,'{"arbitro": "Raphael Claus", "auxiliares": ["Danilo Ricardo Simon Manis", "Nailton Junior de Sousa Oliveira"], "var": "Wagner Reway"}');
INSERT INTO matches VALUES(208439,'13/05/2026','2026-05-13',5182,681,'casa',2,2,'Vasco empatou com o Paysandu em 2 a 2 em São Januário, pela volta da 5ª fase da Copa do Brasil 2026, e avançou às oitavas pelo agregado de 4 a 2. Gols oficiais na súmula CBF: Johan Rojas de pênalti aos 35''/1T, Thiago Mendes aos 41''/1T, Thayllon aos +2/1T e gol contra de Saldivia aos 1''/2T. NetVasco registra Rojas aos 34''/1T e Thayllon aos 47''/1T; foram usados os tempos da súmula CBF, convertendo o acréscimo de Thayllon para 47. Público pagante confirmado por imagem do boletim financeiro enviada pelo usuário: 15.775; público presente: 16.653; renda: R$ 1.081.866,00. Thiago Mendes era o capitão e foi expulso diretamente aos 44''/2T por cotovelada em Caio Mello, segundo súmula. Jair, Mateus Carvalho e Cuiabano estavam fora por lesão; não havia pendurados no Vasco. Avellar e Ramon Rique não enfrentaram o Paysandu por não estarem inscritos na Copa do Brasil. CBF registrou o reserva 98 como João Pedro Murilo de Paula Morais, normalizado para JP no banco local; registrou o reserva 11 como Carlos Andres Gomez Hinestroza, normalizado para Andrés Gómez; registrou o titular 88 como Barros, normalizado para Cauan Barros. Braulio da Silva Machado não foi encontrado na lista local de árbitros; cadastrar antes de importar se o importador não criar automaticamente. Súmula informa que nada houve de anormal e que foi respeitado 1 minuto de silêncio em homenagem póstuma a torcedores do Vasco.',2439,NULL,'{"titulares_por_posicao": {"Goleiro": ["Léo Jardim"], "Lateral-Direito": ["Paulo Henrique"], "Zagueiro": ["Saldivia", "Lucas Freitas"], "Lateral-Esquerdo": ["Lucas Piton"], "Volante": ["Cauan Barros", "Thiago Mendes"], "Meio-Campista": ["Johan Rojas", "Marino"], "Atacante": ["David", "Brenner"]}, "reservas": ["Daniel Fuzato", "Puma Rodríguez", "Tche Tche", "Matheus França", "Andrés Gómez", "Nuno Moreira", "Hugo Moura", "Adson", "Pablo", "Walace Falcão", "Claudio Spinelli", "JP"], "substituicoes": [{"jogador_saiu": "Paulo Henrique", "jogador_entrou": "Puma Rodríguez", "minuto": 5, "periodo": "2T"}, {"jogador_saiu": "Marino", "jogador_entrou": "Adson", "minuto": 15, "periodo": "2T"}, {"jogador_saiu": "David", "jogador_entrou": "Claudio Spinelli", "minuto": 15, "periodo": "2T"}, {"jogador_saiu": "Brenner", "jogador_entrou": "Andrés Gómez", "minuto": 15, "periodo": "2T"}, {"jogador_saiu": "Johan Rojas", "jogador_entrou": "Nuno Moreira", "minuto": 25, "periodo": "2T"}], "nao_relacionados": ["Alison", "Allan Vitor", "Andrey Fernandes", "Avellar", "Breno Vereza", "Bruno André", "Carlos Cuesta", "Gustavo Guimarães", "João Vitor", "Juninho", "Lukas Zucarello", "Phillipe Gabriel", "Ramon Rique", "Robert Renan", "Samuel Jesus"], "lesionados": ["Jair", "Mateus Carvalho", "Cuiabano"], "suspensos": [], "servindo_selecao": []}','São Januário','19:00','Thiago Mendes',15775,16653,1081866.0,'{"arbitro": "Braulio da Silva Machado", "auxiliares": ["Thiaggo Americano Labes", "Henrique Neu Ribeiro"], "var": "Rafael Traci"}');
CREATE TABLE match_goals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            match_id INTEGER NOT NULL,
            side TEXT NOT NULL,
            player_id INTEGER,
            player_name TEXT NOT NULL,
            goals INTEGER NOT NULL DEFAULT 1,
            club_name TEXT,
            is_disallowed INTEGER NOT NULL DEFAULT 0, goal_minutes_json TEXT NOT NULL DEFAULT '[]', goal_periods_json TEXT NOT NULL DEFAULT '[]',
            FOREIGN KEY (match_id) REFERENCES matches (id) ON DELETE CASCADE,
            FOREIGN KEY (player_id) REFERENCES players (id)
        );
